    DataType ResolveQwen35CudaCacheType(DataType cacheType, DataType computeType) {
        if (cacheType == DataType::FLOAT16 ||
            cacheType == DataType::BFLOAT16 ||
            cacheType == DataType::FP8_E4M3 ||
            IsPackedKVCacheDataType(cacheType)) {
            return cacheType;
        }
        return computeType;
    }

    size_t Qwen35PagedCachePageBytes(
            DataType type, int pageLen, int numHeads, int headDim) {
        AssertInFastLLM(pageLen > 0 && numHeads > 0 && headDim > 0,
                        "Qwen3.5 paged cache page shape is invalid.\n");
        return GetDataBytes(type, (size_t)pageLen * numHeads, headDim);
    }


    Qwen35RequestPhase ClassifyQwen35RequestPhase(const ResponseContext &context) {
        if (context.longPrefill.inProgress &&
            context.longPrefill.cursor < context.longPrefill.total) {
            return Qwen35RequestPhase::ContinuedPrefill;
        }
        return context.preTokens == 0 ?
            Qwen35RequestPhase::NewPrefill : Qwen35RequestPhase::Decode;
    }

    bool BeginQwen35LongPrefill(
            ResponseContext &context,
            int total,
            uint64_t ticket,
            const std::map<PagedCacheManager*, int> &reservedPages) {
        if (context.longPrefill.inProgress || context.preTokens != 0 ||
            total <= 0 || total != (int)context.currentTokens.size()) {
            return false;
        }
        for (const auto &item : reservedPages) {
            if (item.first == nullptr || item.second < 0) {
                return false;
            }
        }
        context.longPrefill.inProgress = true;
        context.longPrefill.total = total;
        context.longPrefill.cursor = 0;
        context.longPrefill.mtpViable = true;
        context.longPrefill.ticket = ticket;
        context.longPrefill.reservedPages = reservedPages;
        return true;
    }

    Qwen35LongPrefillQuantum PlanQwen35LongPrefillQuantum(
            const ResponseContext &context,
            int chunkSize) {
        Qwen35LongPrefillQuantum quantum;
        const Qwen35LongPrefillProgress &progress = context.longPrefill;
        if (!progress.inProgress || chunkSize <= 0 || progress.total <= 0 ||
            progress.cursor < 0 || progress.cursor >= progress.total ||
            context.preTokens != progress.cursor) {
            return quantum;
        }
        quantum.cursor = progress.cursor;
        quantum.length = std::min(chunkSize, progress.total - progress.cursor);
        quantum.baseTokens = context.cacheLen + progress.cursor;
        quantum.isLast = progress.cursor + quantum.length == progress.total;
        quantum.producesOutput = quantum.isLast;
        return quantum;
    }

    bool CommitQwen35LongPrefillQuantum(
            ResponseContext &context,
            const Qwen35LongPrefillQuantum &quantum,
            bool mtpViable) {
        Qwen35LongPrefillProgress &progress = context.longPrefill;
        if (!progress.inProgress || quantum.length <= 0 ||
            quantum.cursor != progress.cursor ||
            context.preTokens != progress.cursor ||
            quantum.baseTokens != context.cacheLen + progress.cursor ||
            quantum.cursor + quantum.length > progress.total) {
            return false;
        }
        bool isLast = quantum.cursor + quantum.length == progress.total;
        if (quantum.isLast != isLast || quantum.producesOutput != isLast) {
            return false;
        }
        progress.cursor += quantum.length;
        context.preTokens += quantum.length;
        progress.mtpViable = progress.mtpViable && mtpViable;
        if (isLast) {
            progress.inProgress = false;
            progress.reservedPages.clear();
        }
        return true;
    }

    int SelectQwen35LongPrefillHandle(
            const std::vector<std::tuple<int, uint64_t> > &candidates,
            uint64_t lastTicket) {
        int afterHandle = -1;
        uint64_t afterTicket = UINT64_MAX;
        int firstHandle = -1;
        uint64_t firstTicket = UINT64_MAX;
        for (const auto &candidate : candidates) {
            int handle = std::get<0>(candidate);
            uint64_t ticket = std::get<1>(candidate);
            if (handle < 0) {
                continue;
            }
            if (ticket < firstTicket ||
                (ticket == firstTicket && (firstHandle < 0 || handle < firstHandle))) {
                firstTicket = ticket;
                firstHandle = handle;
            }
            if (ticket > lastTicket &&
                (ticket < afterTicket ||
                 (ticket == afterTicket && (afterHandle < 0 || handle < afterHandle)))) {
                afterTicket = ticket;
                afterHandle = handle;
            }
        }
        return afterHandle >= 0 ? afterHandle : firstHandle;
    }

    bool CanAdmitQwen35LongPrefill(int residentRequests, int schedulerLanes) {
        return residentRequests >= 0 && schedulerLanes > 0 &&
               residentRequests < schedulerLanes;
    }

    bool CanReserveQwen35LongPrefillPages(
            const std::vector<Qwen35PageReservationBudget> &budgets) {
        for (const auto &budget : budgets) {
            if (budget.reserved < 0 || budget.needed < 0 || budget.free < 0 ||
                (long long)budget.reserved + budget.needed > budget.free) {
                return false;
            }
        }
        return true;
    }

    int SelectQwen35SchedulerLanes(
            int configuredLanes,
            bool canUseMtpBatchForward,
            bool batchedMtpEnabled,
            int mtpSnapshotBatchLimit) {
        configuredLanes = std::max(1, configuredLanes);
        if (!canUseMtpBatchForward) {
            return 1;
        }
        if (!batchedMtpEnabled) {
            return configuredLanes;
        }
        return std::min(
            configuredLanes, std::max(1, mtpSnapshotBatchLimit));
    }

    int SelectQwen35ResidentRequestLimit(
            int configuredLanes,
            int schedulerLanes,
            bool interleaveLongPrefill) {
        configuredLanes = std::max(1, configuredLanes);
        schedulerLanes = std::max(1, schedulerLanes);
        return interleaveLongPrefill ? configuredLanes : schedulerLanes;
    }

    bool Qwen35UsePlainResidentDecodeBatch(
            bool plainBatchEnabled,
            bool batchedMtpEnabled,
            int schedulerLanes,
            int residentDecodeRequests) {
        return plainBatchEnabled &&
               !batchedMtpEnabled &&
               schedulerLanes > 1 &&
               residentDecodeRequests > 1;
    }

#ifdef USE_CUDA
    Qwen35DivisionScheme BuildQwen35LinearOutProjScheme(
            const Qwen35DivisionScheme &keyHeadScheme,
            int numKHeads,
            int numVHeads,
            int headVDim,
            int quantBlock,
            bool tiledColumns) {
        if (!(numKHeads > 0 && numVHeads >= numKHeads &&
              numVHeads % numKHeads == 0 && headVDim > 0)) {
            throw std::runtime_error(
                "Qwen3.5 out_proj TP split got invalid head metadata.");
        }
        quantBlock = std::max(1, quantBlock);
        const int valueHeadsPerKey = numVHeads / numKHeads;
        Qwen35DivisionScheme ret;
        for (auto &it : keyHeadScheme) {
            ret[it.first];
            if (it.second.size() > 1) {
                throw std::runtime_error(
                    "Qwen3.5 out_proj TP split requires one contiguous key-head range per device.");
            }
            for (auto &range : it.second) {
                if (!(range.first >= 0 && range.second > range.first &&
                      range.second <= numKHeads)) {
                    throw std::runtime_error(
                        "Qwen3.5 out_proj TP split got an invalid key-head range.");
                }
                if (tiledColumns) {
                    for (int r = 0; r < valueHeadsPerKey; r++) {
                        const int start = (r * numKHeads + range.first) * headVDim;
                        const int end = (r * numKHeads + range.second) * headVDim;
                        if (!(start % quantBlock == 0 && end % quantBlock == 0)) {
                            throw std::runtime_error(
                                "Qwen3.5 tiled out_proj TP split is not quant-block aligned.");
                        }
                        ret[it.first].push_back({start, end});
                    }
                } else {
                    const int start = range.first * valueHeadsPerKey * headVDim;
                    const int end = range.second * valueHeadsPerKey * headVDim;
                    if (!(start % quantBlock == 0 && end % quantBlock == 0)) {
                        throw std::runtime_error(
                            "Qwen3.5 grouped out_proj TP split is not quant-block aligned.");
                    }
                    ret[it.first].push_back({start, end});
                }
            }
        }
        return ret;
    }
#endif

    static std::string Qwen35MoeExpertPrefix(int layer, int expert) {
        return Qwen3_5Model::language_prefix + "layers." + std::to_string(layer) +
               ".mlp.experts." + std::to_string(expert) + ".";
    }

    static std::string Qwen35MoeFusedWeightName(int layer, const std::string &kind) {
        return Qwen3_5Model::language_prefix + "layers." + std::to_string(layer) +
               ".mlp.fused_experts." + kind + "_proj.weight";
    }

    static std::string Qwen35MoeExpertWeightName(int layer, int expert, const std::string &kind) {
        return Qwen35MoeExpertPrefix(layer, expert) + kind + "_proj.weight";
    }

    static bool Qwen35MoeParseExpertWeightName(const std::string &name,
                                               int &layer, int &expert, std::string &kind) {
        const std::string prefix = Qwen3_5Model::language_prefix + "layers.";
        if (!StartWith(name, prefix)) {
            return false;
        }
        size_t pos = prefix.size();
        if (pos >= name.size() || !std::isdigit((unsigned char)name[pos])) {
            return false;
        }
        layer = 0;
        while (pos < name.size() && std::isdigit((unsigned char)name[pos])) {
            layer = layer * 10 + (name[pos] - '0');
            pos++;
        }
        const std::string mid = ".mlp.experts.";
        if (name.compare(pos, mid.size(), mid) != 0) {
            return false;
        }
        pos += mid.size();
        if (pos >= name.size() || !std::isdigit((unsigned char)name[pos])) {
            return false;
        }
        expert = 0;
        while (pos < name.size() && std::isdigit((unsigned char)name[pos])) {
            expert = expert * 10 + (name[pos] - '0');
            pos++;
        }
        const std::string suffix = "_proj.weight";
        if (name.compare(pos, 1, ".") != 0 || name.size() <= pos + 1 + suffix.size() ||
            name.compare(name.size() - suffix.size(), suffix.size(), suffix) != 0) {
            return false;
        }
        kind = name.substr(pos + 1, name.size() - pos - 1 - suffix.size());
        return kind == "gate" || kind == "up" || kind == "gateup" || kind == "down";
    }

    static int Qwen35MoeSourceLoadPriority(const std::string &name, int numExperts) {
        int layer = -1, expert = -1;
        std::string kind;
        if (!Qwen35MoeParseExpertWeightName(name, layer, expert, kind)) {
            return 0;
        }
        (void)expert;
        (void)numExperts;
        int layerStride = 3;
        int order = (kind == "down") ? 2 : (kind == "up" ? 1 : 0);
        return -100000000 + layer * layerStride + order;
    }

    static bool Qwen35MoeIsFusedFp8Type(DataType dataType) {
        return dataType == DataType::FP8_E4M3 ||
               dataType == DataType::FP8_E4M3_BLOCK_128;
    }

    static bool Qwen35MoeIsTrueString(const std::string &value) {
        std::string lowered = value;
        std::transform(lowered.begin(), lowered.end(), lowered.begin(),
                       [](unsigned char c) { return (char)std::tolower(c); });
        return lowered == "true" || lowered == "1" || lowered == "yes" || lowered == "on";
    }

    static bool Qwen35MoeDisableFusedMoe() {
        const char *env = std::getenv("FASTLLM_QWEN35_MOE_DISABLE_FUSED_MOE");
        if (env == nullptr) {
            env = std::getenv("FASTLLM_QWEN3_MOE_DISABLE_FUSED_MOE");
        }
        return env != nullptr && Qwen35MoeIsTrueString(env);
    }

    // ---- mtpCacheMutex 持有者追踪(死锁诊断) --------------------------------
    // 现象: MTPLoop 卡在 mtpCacheMutex 上, 而 gdb 显示**没有任何线程在跑**
    //   (其余 8 线程全在 __syscall_cancel_arch)。所有用法都是 lock_guard,
    //   不存在异常展开漏解锁; 但 Qwen35MTPLoop 是 3100 行、6 处加锁点、
    //   lambda 全被内联, 栈上看不出中间帧 —— 纯静态分析不可靠。
    // 所以让锁自己说话: 记录当前持有者的 tid 与加锁位置, 等锁超时就打印出来。
    // FASTLLM_MTP_LOCK_DEBUG=1 开启; 默认关闭时退化成普通 lock_guard, 零额外开销。
    struct Qwen35MtpLockState {
        std::atomic<unsigned long long> holderTid{0};
        std::atomic<const char*> holderWhere{nullptr};
        std::atomic<int> holderLine{0};
    };

    static Qwen35MtpLockState &Qwen35MtpLockStateOf(std::mutex *m) {
        static std::mutex mapMutex;
        static std::map<std::mutex*, Qwen35MtpLockState*> states;
        std::lock_guard<std::mutex> g(mapMutex);
        auto it = states.find(m);
        if (it == states.end()) {
            it = states.emplace(m, new Qwen35MtpLockState()).first;
        }
        return *it->second;
    }

    static bool Qwen35MtpLockDebugEnabled() {
        static const bool on = []() {
            const char *env = std::getenv("FASTLLM_MTP_LOCK_DEBUG");
            return env != nullptr && env[0] != 0 && env[0] != '0';
        }();
        return on;
    }

    static unsigned long long Qwen35SelfTid() {
        return (unsigned long long)std::hash<std::thread::id>{}(
            std::this_thread::get_id());
    }

    class Qwen35MtpLockGuard {
    public:
        Qwen35MtpLockGuard(std::mutex &m, const char *where, int line)
                : mutex_(m), debug_(Qwen35MtpLockDebugEnabled()) {
            if (!debug_) {
                mutex_.lock();
                return;
            }
            auto &st = Qwen35MtpLockStateOf(&mutex_);
            const auto deadline = std::chrono::steady_clock::now() +
                                  std::chrono::seconds(10);
            bool warned = false;
            while (!mutex_.try_lock()) {
                if (!warned &&
                    std::chrono::steady_clock::now() > deadline) {
                    warned = true;
                    const char *hw = st.holderWhere.load();
                    printf("[MtpLock] 等待超过 10s: 本线程 tid=%llu 在 %s:%d; "
                           "持有者 tid=%llu 在 %s:%d\n",
                           Qwen35SelfTid(), where, line,
                           st.holderTid.load(),
                           hw == nullptr ? "?" : hw,
                           st.holderLine.load());
                    fflush(stdout);
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(20));
            }
            st.holderTid.store(Qwen35SelfTid());
            st.holderWhere.store(where);
            st.holderLine.store(line);
        }

        ~Qwen35MtpLockGuard() {
            if (debug_) {
                auto &st = Qwen35MtpLockStateOf(&mutex_);
                st.holderTid.store(0);
                st.holderWhere.store(nullptr);
                st.holderLine.store(0);
            }
            mutex_.unlock();
        }

        Qwen35MtpLockGuard(const Qwen35MtpLockGuard &) = delete;
        Qwen35MtpLockGuard &operator=(const Qwen35MtpLockGuard &) = delete;

    private:
        std::mutex &mutex_;
        const bool debug_;
    };

    static constexpr int QWEN35_MTP_LOG_INTERVAL = 64;
    static constexpr int QWEN35_MTP_MAX_DRAFTS = 9;
    static constexpr int QWEN35_MTP_FAST_SEQ_MAX = QWEN35_MTP_MAX_DRAFTS + 1;
    static constexpr float QWEN35_MTP_TYPICAL_POSTERIOR_THRESHOLD = 0.09f;
    static constexpr float QWEN35_MTP_TYPICAL_POSTERIOR_ALPHA = 0.3f;

    // 【上游BUMP勿回退】回退成"只用 typical acceptance"会让逐字抄写被偶发替换:
    // 文件路径/函数名/commit hash/工具调用 JSON 这些只有一个 token 对的位置会被
    // 换成"看着像"的邻近 token。上游没有 exact 分支, 合并时若看到本段与上游不同,
    // 保留本段。
    // ---- MTP 接受判据 -------------------------------------------------------
    // typical acceptance (Medusa 系) 只要求"目标模型给这个 draft token 的概率
    // 超过阈值"就接受, **不做拒绝采样的残差修正, 因此不保持目标分布**。
    // 对普通行文几乎无害(很多 token 可互换), 但 agent 干活靠的是**逐字抄写**:
    // 文件路径、函数名、commit hash、工具调用 JSON —— 这些位置只有一个 token
    // 是对的。此时阈值 0.09 会偶尔放过"看着像"的那个:
    //     写完 "Proto-" 后目标分布约 UI=0.85 / U=0.10;
    //     draft 提议 "U", 0.10 > 0.09 -> 接受 -> 输出 "Proto-U"。
    // 生产日志里正是这个形态(Proto-U / ProtoUI / Dotments / eza), 破坏率约
    // 0.05%~1.3%, 足以让 agent cd 进不存在的目录, 再据此推翻自己的判断。
    //
    // 默认改为 exact acceptance: 仅当 draft 与目标模型**实际采样出的 token**
    // 相同才接受。这样每个吐出的 token 都由目标模型自己产生, 输出逐字节等价
    // 于不开投机解码; 代价只是接受率下降(速度), 不是正确性。
    // 需要拿正确性换吞吐时设 FASTLLM_QWEN35_MTP_EXACT_ACCEPT=0 退回 typical。
    static bool Qwen35MtpExactAcceptance() {
        static const bool value = []() {
            const char *env = std::getenv("FASTLLM_QWEN35_MTP_EXACT_ACCEPT");
            return env == nullptr ? true : Qwen35MoeIsTrueString(env);
        }();
        return value;
    }

    static float Qwen35MtpEnvFloat(const char *name, float fallback) {
        const char *env = std::getenv(name);
        if (env == nullptr || *env == 0) {
            return fallback;
        }
        char *end = nullptr;
        float parsed = std::strtof(env, &end);
        if (end == env || !std::isfinite(parsed) || parsed < 0.0f) {
            return fallback;
        }
        return parsed;
    }

    static float Qwen35MtpTypicalThreshold() {
        static const float value = Qwen35MtpEnvFloat(
            "FASTLLM_QWEN35_MTP_TYPICAL_THRESHOLD",
            QWEN35_MTP_TYPICAL_POSTERIOR_THRESHOLD);
        return value;
    }

